"""Build the editable companion deck from a reviewable storyboard. No training or API calls."""
from pathlib import Path
import json, html, re, os, shutil
ROOT=Path(__file__).resolve().parents[1]
# Keep the deck's copy in sync when building in the kit. The source ZIP carries
# that same SVG and also builds without a parent checkout.
LAB_SOURCE=ROOT.parents[1]/'src/forge_workshop_kit/assets/solar-lab.svg'
LAB_ASSET=ROOT/'public/images/solar-lab.svg'
if LAB_SOURCE.exists():
    shutil.copy2(LAB_SOURCE,LAB_ASSET)
assert LAB_ASSET.exists(), 'The Solar Forecasting Lab artwork is missing.'
recorded=json.loads((ROOT/'public/recorded-study.json').read_text())
image_results=next(row['result']['metrics_by_version'] for row in recorded['stages'] if row['name']=='images/final-comparison')
relative_gain=1-image_results['agent']['error']/image_results['manual']['error']
BASE='/' + os.environ.get('DECK_BASE', '').strip('/') + '/'
if BASE == '//': BASE = '/'
slides=[]
def add(key,title,body='',notes='',kind='',time='',answer=None):
    slides.append(dict(key=key,title=title,body=body,notes=notes,kind=kind,time=time,answer=answer))
def note(text):return '<div class="bottom-note">'+text+'</div>'
def code(text,lang='python'):return f'```{lang}\n{text}\n```\n\n'
def cols(a,b):return '<div class="two-col">\n<div>\n\n'+a+'\n\n</div>\n<div>\n\n'+b+'\n\n</div>\n</div>'
def turn(key,title,task,actions,done,notes,time,answer=None):
    body=f'<div class="task">{task}</div><ol class="exercise-controls">'+''.join('<li>'+a+'</li>' for a in actions)+f'</ol><div class="done">Check your work: {done}</div>'
    add(key,title,body,notes,'exercise',time,answer)
def pic(name,alt,caption):return f'<img class="solar-photo" src="/images/{name}" alt="{html.escape(alt)}"><div class="image-caption">{caption}</div>'
def screen(name, alt, prompt, url, link_label, caption):
    return (f'<a class="product-screen {name.removesuffix(".png")}" href="/images/{name}" target="_blank" aria-label="Open full-size capture">'
            f'<img src="/images/{name}" alt="{html.escape(alt)}"></a>'
            f'<div class="product-caption"><span>{prompt}</span><a href="{url}">{link_label} ↗</a></div>'
            f'<div class="image-caption">{caption}</div>')
