SOLAR_ARTIFACT='https://forge.coreweave.com/wandb/wandb/forge-workshop-kit/artifacts/workshop-execution/execution-f5e5d198bc9479f78d9a4b1c8c8979e3/v0'
PENDING_TEMPLATE='https://forge.coreweave.com/notebooks/Tm90ZWJvb2s6MTU3NzQ=/view'
PENDING_WORKSPACE='https://forge.coreweave.com/wandb/wandb/forge-workshop-kit?nw=nkyxiy1o6wn'
PENDING_REPORT='https://forge.coreweave.com/wandb/wandb/forge-workshop-kit/reports/pending-direct-teaching:-51a0006f--VmlldzoxODMwMjcxMA=='
PENDING_TRACE='https://forge.coreweave.com/agent-lens/wandb/forge-workshop-kit/conversations/370ae4263372ca1de91d7308e66d0d3d/spans/turns/fbb084c1ce00e6ade53a3d56ed7760fe/spans/2af0208bf11b7217'
